# Analyzing each changed case manually since we don't have the library functions
inputs = ['eibci', 'fyudg', 'ijvf', 'djc', 'ixh']
outputs = ['eibeyi', 'fuhdhudg', 'ijvf', 'djey', 'ixh']

# Find changed pairs
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Manual analysis of differences
print("\nDetailed analysis:")
for idx, inp, outp in changed_pairs:
    print(f"Example {idx}: '{inp}' -> '{outp}'")
    # Find what changed
    if len(inp) == len(outp):
        diff_positions = []
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                diff_positions.append(i)
        print(f"  Positions with differences: {diff_positions}")
    elif len(outp) > len(inp):
        # Insertions
        print(f"  Insertion detected (length increased by {len(outp)-len(inp)})")
    else:
        # Deletions
        print(f"  Deletion detected (length decreased by {len(inp)-len(outp)})")
    print()

