# Let me look more carefully at each transformation
examples = [
    ('eibci', 'eibeyi'),  # c -> ey
    ('fyudg', 'fuhdhudg'), # y -> uhd  
    ('djc', 'djey')        # c -> ey
]

print("Detailed character-by-character analysis:")
for i, (inp, outp) in enumerate(examples):
    print(f"\nExample {i}: '{inp}' -> '{outp}'")

    # Find the differences
    min_len = min(len(inp), len(outp))
    pos = -1
    for j in range(min_len):
        if inp[j] != outp[j]:
            pos = j
            break

    if pos == -1:
        if len(inp) != len(outp):
            pos = min_len
        else:
            print("  No differences found")
            continue

    print(f"  First difference at position {pos}")

    # What's the pattern?
    if pos < len(inp) and pos < len(outp):
        print(f"  Character at {pos} in input: '{inp[pos]}' -> '{outp[pos]}'")
    elif pos < len(inp):
        print(f"  Character at {pos} in input: '{inp[pos]}' (deletion)")
    elif pos < len(outp):
        print(f"  Character at {pos} in output: '{outp[pos]}' (insertion)")

    # For more complex cases, let's see the substring approach
    if len(outp) > len(inp):
        # Look for insertion pattern
        for j in range(len(inp)):
            if j + len(inp) <= len(outp):
                # Check if we can match inp with part of outp
                if inp == outp[j:j+len(inp)]:
                    print(f"  Input matches output from position {j} to {j+len(inp)}")
                    # Check what's inserted
                    inserted = outp[:j] + outp[j+len(inp):]
                    print(f"  Inserted portion: '{inserted}'")
                    break
    elif len(inp) > len(outp):
        # Look for deletion pattern
        for j in range(len(outp)):
            if j + len(outp) <= len(inp):
                if outp == inp[j:j+len(outp)]:
                    print(f"  Output matches input from position {j} to {j+len(outp)}")
                    # Check what's deleted
                    deleted = inp[:j] + inp[j+len(outp):]
                    print(f"  Deleted portion: '{deleted}'")
                    break

